  "id": "db-07-s3-redshift-load-plan",
  "goal_id": "db-07-s3-redshift-load",
  "version": 1,
  "tasks": [
    {
      "id": "validate_s3_files",
      "description": "Validate that all required S3 files are present for the load.",
      "action": "check",
      "target": "S3",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "S3 bucket is accessible",
          "fact": "s3_accessible",
          "established_by": "env"
        }
      ]
    },
    {
      "id": "prepare_manifest",
      "description": "Generate a manifest file for the Parquet data in S3.",
      "action": "generate",
      "target": "manifest",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "S3 files are validated",
          "fact": "files_validated",
          "established_by": "validate_s3_files"
        }
      ]
    },
    {
      "id": "load_to_staging",
