      "action": "load",
      "target": "Redshift",
      "risk_class": "high",
      "rollback": {
        "trigger": "COPY failure",
        "action": "restore previous state of staging",
        "safety_guard": "ensure staging state is prior to load"
      },
      "verification": {
        "what": "row counts match",
        "how": "compare manifest and staging row count",
        "expected": "row counts equal"
      },
      "preconditions": [
        {
          "description": "Manifest file is prepared",
          "fact": "manifest_prepared",
