        "trigger": "swap failure",
        "action": "return to previous production state",
        "safety_guard": "check for integrity of previous partition"
      },
      "verification": {
        "what": "row counts match",
        "how": "compare production and staging row count",
        "expected": "row counts equal"
      },
      "preconditions": [
        {
