      "description": "Notify downstream consumers that data is fresh and ready for use.",
      "action": "notify",
      "target": "consumers",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "VACUUM and ANALYZE completed",
          "fact": "vacuum_analyzed",
          "established_by": "vacuum_and_analyze"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "validate_s3_files",
      "to_task": "prepare_manifest",
