    },
    {
      "from_task": "prepare_manifest",
      "to_task": "load_to_staging",
      "kind": "hard"
    },
    {
      "from_task": "load_to_staging",
      "to_task": "swap_partitions",
      "kind": "hard"
    },
    {
      "from_task": "swap_partitions",
      "to_task": "vacuum_and_analyze",
      "kind": "hard"
    },
    {
      "from_task": "vacuum_and_analyze",
      "to_task": "notify_consumers",
      "kind": "hard"
    }
  ]
}
